mapper.select:
SELECT SUM(PayAmount) AS succeedpayamount,
count(1) AS succeedcount
FROM (
SELECT PayAmount
FROM t_depositorder td

    (OrderStatus = 3 OR OrderStatus = 4)


        and td.SupplierBranchID = #{supplierbranchid}


        and td.CreateTime >= #{querytime}



UNION ALL

SELECT PayAmount
FROM t_withdraworder td

    (OrderStatus = 3 OR OrderStatus = 4)


        and td.SupplierBranchID = #{supplierbranchid}


        and td.CreateTime >= #{querytime}

    AND OrderType = 0



UNION ALL

SELECT PayAmount
FROM t_thirddepositorder td


    (OrderStatus = 3 OR OrderStatus = 4)


        and td.SupplierBranchID = #{supplierbranchid}


        and td.CreateTime >= #{querytime}


UNION ALL

SELECT PayAmount
FROM t_thirdwithdraworder td

    (OrderStatus = 3 OR OrderStatus = 4)
    and  td.IsFastPay  <>  10

        and td.SupplierBranchID = #{supplierbranchid}


        and td.CreateTime >= #{querytime}


) t

